(function (){function isLocalOrPrivate(h){if (!h) return true;if (h==='127.0.0.1' || h==='localhost' || h==='::1') return true;if (h.charAt(0)==='[') return true;if (/\.local$/.test(h)) return true;if (/^10\./.test(h)) return true;if (/^192\.168\./.test(h)) return true;if (/^172\.(1[6-9]|2\d|3[01])\./.test(h)) return true;if (/^169\.254\./.test(h)) return true;if (h.indexOf('.')===-1) return true;return false}var allowed=(window.LW_ALLOWED_HOSTS && window.LW_ALLOWED_HOSTS.length)?window.LW_ALLOWED_HOSTS:["hnbsd.ct.ws","www.hnbsd.ct.ws","127.0.0.1","localhost"];var host=(window.location.hostname || "").toLowerCase();window.LWIsLocalHost=isLocalOrPrivate;if (isLocalOrPrivate(host)) return;var ok=allowed.some(function (d){d=String(d || '').toLowerCase();return d !=='' && (host===d || host.slice(-(d.length+1))==="."+d)});if (ok) return;var canon=(window.LW_CANONICAL_HOST || "").toLowerCase();if (!canon) return;var proto=(window.location.protocol==="https:")?"https:":"http:";var target=proto+"//"+canon+"/";function showBanner(){try{var bar=document.createElement("div");bar.setAttribute("role","alert");bar.style.cssText=["position:fixed","left:0","right:0","top:0","z-index:2147483647","padding:10px 14px","font:14px/1.5 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif","background:#FFF4E5","color:#8A5300","border-bottom:1px solid #F0D9B5","display:flex","align-items:center","gap:10px","flex-wrap:wrap"].join(";");var txt=document.createElement("span");txt.style.flex="1";txt.textContent="你正在访问非官方地址 "+host+"，为保护账号安全请使用官方站点。";var go=document.createElement("a");go.href=target;go.textContent="前往官方站点";go.style.cssText="color:#8A5300;font-weight:600;text-decoration:underline;white-space:nowrap";bar.appendChild(txt);bar.appendChild(go);(document.body || document.documentElement).appendChild(bar)}catch (e){}}if (document.readyState==="loading"){document.addEventListener("DOMContentLoaded",showBanner,{once:true})}else{showBanner()}})();